import pandas as pd
import numpy as np
import json
import sys

def to_num(x):
    if pd.isna(x):
        return None
    return float(x)

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    # ---- TOTALS ----
    rev_tw = df['Revenue_TW'].sum(skipna=True)
    rev_lw = df['Revenue_LW'].sum(skipna=True)
    rev_ly_series = df['Revenue_LY'].dropna()
    rev_ly = rev_ly_series.sum() if not rev_ly_series.empty else None

    units_tw = df['Units_TW'].sum(skipna=True)
    units_lw = df['Units_LW'].sum(skipna=True)
    orders_tw = df['Orders_TW'].sum(skipna=True)
    orders_lw = df['Orders_LW'].sum(skipna=True)

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": round(float(rev_tw), 2),
        "formula": "sum(Revenue_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": round(float(rev_lw), 2),
        "formula": "sum(Revenue_LW)"
    })
    if rev_ly is not None:
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "LY",
            "value": round(float(rev_ly), 2),
            "formula": "sum(Revenue_LY)"
        })

    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": round(float(units_tw), 2),
        "formula": "sum(Units_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "LW",
        "value": round(float(units_lw), 2),
        "formula": "sum(Units_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": round(float(orders_tw), 2),
        "formula": "sum(Orders_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "LW",
        "value": round(float(orders_lw), 2),
        "formula": "sum(Orders_LW)"
    })

    if rev_lw and rev_lw != 0:
        wow_total = (rev_tw - rev_lw) / rev_lw * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": round(float(wow_total), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    if rev_ly and rev_ly != 0:
        yoy_total = (rev_tw - rev_ly) / rev_ly * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": round(float(yoy_total), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    # ---- TOP ENTITY BY RANK ----
    if 'Rank' in df.columns and not df['Rank'].isna().all():
        top_row = df.loc[df['Rank'].idxmin()]
        facts.append({
            "entity": top_row['Entity'], "metric": "rank", "period": "TW",
            "value": to_num(top_row['Rank']),
            "formula": "Rank"
        })
        facts.append({
            "entity": top_row['Entity'], "metric": "revenue", "period": "TW",
            "value": round(float(top_row['Revenue_TW']), 2) if not pd.isna(top_row['Revenue_TW']) else None,
            "formula": "Revenue_TW"
        })
        if not pd.isna(top_row.get('Share_Pct', np.nan)):
            facts.append({
                "entity": top_row['Entity'], "metric": "share", "period": "TW",
                "value": round(float(top_row['Share_Pct']), 1),
                "formula": "Share_Pct"
            })

    # ---- PER ENTITY SHARE / RANK ----
    for _, row in df.iterrows():
        ent = row['Entity']
        if not pd.isna(row.get('Share_Pct', np.nan)):
            facts.append({
                "entity": ent, "metric": "share", "period": "TW",
                "value": round(float(row['Share_Pct']), 1),
                "formula": "Share_Pct"
            })

    # ---- BIGGEST WoW MOVERS ----
    wow_df = df.dropna(subset=['WoW_Pct'])
    if not wow_df.empty:
        best_wow = wow_df.loc[wow_df['WoW_Pct'].idxmax()]
        worst_wow = wow_df.loc[wow_df['WoW_Pct'].idxmin()]
        facts.append({
            "entity": best_wow['Entity'], "metric": "revenue", "period": "WoW",
            "value": round(float(best_wow['WoW_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })
        if worst_wow['Entity'] != best_wow['Entity']:
            facts.append({
                "entity": worst_wow['Entity'], "metric": "revenue", "period": "WoW",
                "value": round(float(worst_wow['WoW_Pct']), 1),
                "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
            })

    # ---- BIGGEST YoY MOVERS ----
    yoy_df = df.dropna(subset=['YoY_Pct'])
    if not yoy_df.empty:
        best_yoy = yoy_df.loc[yoy_df['YoY_Pct'].idxmax()]
        worst_yoy = yoy_df.loc[yoy_df['YoY_Pct'].idxmin()]
        facts.append({
            "entity": best_yoy['Entity'], "metric": "revenue", "period": "YoY",
            "value": round(float(best_yoy['YoY_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })
        if worst_yoy['Entity'] != best_yoy['Entity']:
            facts.append({
                "entity": worst_yoy['Entity'], "metric": "revenue", "period": "YoY",
                "value": round(float(worst_yoy['YoY_Pct']), 1),
                "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
            })

    # ---- PER ENTITY REVENUE TW/LW/LY, UNITS, ORDERS ----
    for _, row in df.iterrows():
        ent = row['Entity']
        if not pd.isna(row['Revenue_TW']):
            facts.append({
                "entity": ent, "metric": "revenue", "period": "TW",
                "value": round(float(row['Revenue_TW']), 2),
                "formula": "Revenue_TW"
            })
        if not pd.isna(row['Units_TW']):
            facts.append({
                "entity": ent, "metric": "units", "period": "TW",
                "value": round(float(row['Units_TW']), 2),
                "formula": "Units_TW"
            })
        if not pd.isna(row['Orders_TW']):
            facts.append({
                "entity": ent, "metric": "orders", "period": "TW",
                "value": round(float(row['Orders_TW']), 2),
                "formula": "Orders_TW"
            })

    # Deduplicate while preserving order, then cap to 25
    seen = set()
    unique_facts = []
    for f in facts:
        key = (f['entity'], f['metric'], f['period'], f['value'])
        if key not in seen:
            seen.add(key)
            unique_facts.append(f)

    unique_facts = unique_facts[:25]

    print(json.dumps(unique_facts))

if __name__ == "__main__":
    main()
